INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (10.85, "2030/12/17 14:59:59", 129901, 100, 1, "2024/03/31 12:00:00", 24, 0, 10142, 0, "訓練成功、おめでとうございます\n褒めるべき時にはしっかり褒めるのも\n教官の務めですものね。それとも、\n罵られる方が好みですか？　クスクス", 7, "エリコ", 100);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (11.15, "2030/12/17 14:59:59", 129901, 101, 1, "2024/03/31 12:00:00", 24, 0, 10142, 0, "厳しい訓練も、終わってみれば\n短く感じるものですわね。\n正直、私は暴れ足りないくらい…\nいえ、何でもありませんわ。クスクス", 2, "エリコ", 101);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (6.4, "2030/12/17 14:59:59", 129901, 102, 7, "2024/03/31 12:00:00", 24, 0, 10142, 0, "行く手を阻む忌々しい邪魔者を\n蹴散らして、見事ゴールイン…！\nまるで私とあのおかたの人生を\n象徴するような道のりでした…", 5, "エリコ", 102);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (0, "2030/12/17 14:59:59", 129901, 103, 3, "2024/03/31 12:00:00", 24, 0, 10142, 0, "まったくもって不甲斐ない結果です\nしかし、挽回の機会はまだありますわ\n次はゴミ虫の地位から脱却できるよう\n死力を尽くしなさい。いいですね？", 3, "エリコ", 103);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (2.43, "2030/12/17 14:59:59", 129901, 104, 2, "2024/03/31 12:00:00", 24, 0, 10142, 0, "クスクス…ああご心配なさらず\nなんとも情けない成績を残す輩には\nどんな罰が相応しいか、考えている\nだけですので…クスクスクス", 8, "エリコ", 104);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (9.08, "2030/12/17 14:59:59", 129901, 105, 4, "2024/03/31 12:00:00", 24, 0, 10142, 0, "私が教官として認められなければ、\nあのおかたを失望させてしまう…\nそれだけはあってはなりません\nあなた方も、わかっていますわね？", 3, "エリコ", 105);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (0, "2030/12/17 14:59:59", 129901, 106, 6, "2024/03/31 12:00:00", 24, 0, 10142, 0, "まずまずの結果ではありますが、\nこの程度で満足してもらっては\n困りますわ。エリコ班の一員として、\nより高みを目指していただきますので", 6, "エリコ", 106);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (10.6, "2030/12/17 14:59:59", 129901, 107, 3, "2024/03/31 12:00:00", 24, 0, 10142, 0, "私の指導を受けながら、この結果は…\nもっと真剣に考えねばなりませんね\nあなた方が怠けずにいるには、\nどんなしつけが必要かを…クスクス", 8, "エリコ", 107);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (7.54, "2030/12/17 14:59:59", 129901, 108, 6, "2024/03/31 12:00:00", 24, 0, 10142, 0, "ひとまず訓練をこなしたご褒美か、\n実力を出しきれたとは言えない罰か…\nみなさんにどちらを与えるべきか\n少し悩む結果ですわね", 4, "エリコ", 108);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (11.5, "2030/12/17 14:59:59", 129901, 109, 2, "2024/03/31 12:00:00", 24, 0, 10142, 0, "なかなかいい戦いぶりでしたわ\nこれもあなた方の頑張りと、何より\n優秀な教官である私の教育の賜物\nそうですわね？　クスクスクス…", 7, "エリコ", 109);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (8.83, "2030/12/17 14:59:59", 129901, 110, 2, "2024/03/31 12:00:00", 24, 0, 10142, 0, "これだけ進めたのならば合格点ですわ\nでも、もっと高みを目指したいと\n思っているのなら…さらなる訓練にも\n付き合って差し上げましょう", 1, "エリコ", 110);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (6.68, "2030/12/17 14:59:59", 129901, 111, 1, "2024/03/31 12:00:00", 24, 0, 10142, 0, "未熟で頼りなかったあなた方が、\n見違えるように成長しました\nなるほど…これこそが、教官冥利に\n尽きるという気持ちなのですね", 2, "エリコ", 111);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (8.8, "2030/12/17 14:59:59", 129901, 112, 6, "2024/03/31 12:00:00", 24, 0, 10142, 0, "まさかあなた方が、私の予想すら\n超える力を発揮するとは…驚きました\nもはやゴミ虫などではありません\n一人前の騎士として胸を張りなさい", 2, "エリコ", 112);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (8.9, "2030/12/17 14:59:59", 129901, 113, 2, "2024/03/31 12:00:00", 24, 0, 10142, 0, "クスクス、見事な働きです\nみなさんならできると信じていました\n他でもない私の指導を受けた、\nエリコ班の優秀な新兵なのですから", 1, "エリコ", 113);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (3.7, "2030/12/17 14:59:59", 129901, 114, 2, "2024/03/31 12:00:00", 24, 0, 10142, 0, "なんてすばらしい成績…！\n今日という日は『あのおかたを想い\nエリコが限界を超えた記念日』として\n歴史に刻まれることでしょう…！", 5, "エリコ", 114);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (7.6, "2030/12/17 14:59:59", 129801, 200, 1, "2024/03/31 12:00:00", 24, 0, 10142, 0, "よし、いい訓練になったな\nおまえたちもよく動けてたし、\nちゃんと成長できてると思うぜ\nその調子で頑張れよっ", 2, "マコト", 200);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (2.25, "2030/12/17 14:59:59", 129801, 201, 2, "2024/03/31 12:00:00", 24, 0, 10142, 0, "ひとまずゴールおめでとう！\nでも、努力は継続してこそだからな\nおまえたちにやる気があるなら、\n何度だって付き合ってやるよ", 1, "マコト", 201);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (3.28, "2030/12/17 14:59:59", 129801, 202, 2, "2024/03/31 12:00:00", 24, 0, 10142, 0, "行軍訓練はこれにて完了！\n…なーんて思ってないよな？\n学んだことが体に染みつくまで\n地道に繰り返すのが練習ってもんさ", 1, "マコト", 202);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (2.98, "2030/12/17 14:59:59", 129801, 203, 4, "2024/03/31 12:00:00", 24, 0, 10142, 0, "みんなに無理をさせちまったか…\nでもこれで諦めることはないぜ\n次はきっとうまくいく。そう信じて\n鍛え続ければ、道は開けるはずだ！", 1, "マコト", 203);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (3, "2030/12/17 14:59:59", 129801, 204, 4, "2024/03/31 12:00:00", 24, 0, 10142, 0, "こいつは悔しい結果だな…\nま、反省点はいろいろあったし\nひとつずつ乗り越えていこう\nあたしたちで力を合わせて、なっ！", 1, "マコト", 204);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (10.3, "2030/12/17 14:59:59", 129801, 205, 1, "2024/03/31 12:00:00", 24, 0, 10142, 0, "おまえたちはまだ未熟な訓練兵、\n失敗を必要以上に悔やむことはねえよ\nでも実戦じゃこうはいかないからな\n次は気合を入れ直していけよっ！", 2, "マコト", 205);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (2.93, "2030/12/17 14:59:59", 129801, 206, 6, "2024/03/31 12:00:00", 24, 0, 10142, 0, "これがおまえたちの全力？\nいやいや、そんなはずはないよなっ\nおまえらならもっと強くなれる！\nあたしが言うんだ、間違いないぜ！", 1, "マコト", 206);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (9.3, "2030/12/17 14:59:59", 129801, 207, 3, "2024/03/31 12:00:00", 24, 0, 10142, 0, "おまえたちの実力を考えりゃ、\nベストを尽くせたとは言えない成績だ\nなら、次やるべきことも決まってる\n気持ちを切り替えて、鍛え直すんだ！", 1, "マコト", 207);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (6.9, "2030/12/17 14:59:59", 129801, 208, 4, "2024/03/31 12:00:00", 24, 0, 10142, 0, "まだまだ課題がある内容だったな～\n無駄な動き、判断の遅れ…\nそういうのをしっかり直していけば、\n記録ももっと伸びるはずだっ", 1, "マコト", 208);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (0, "2030/12/17 14:59:59", 129801, 209, 2, "2024/03/31 12:00:00", 24, 0, 10142, 0, "ここまでいけりゃ、合格点！\nむしろ、最初の頼りなさを思えば\nすげえ成長してるんじゃねえか？\n胸を張れる結果だと思うぜっ！", 2, "マコト", 209);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (5.95, "2030/12/17 14:59:59", 129801, 210, 1, "2024/03/31 12:00:00", 24, 0, 10142, 0, "なかなかハードな訓練だったけど、\nみんなしっかりついてこられたな\n地道に続けた基礎トレの成果が\n形になってる、その証だぜっ", 2, "マコト", 210);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (6.73, "2030/12/17 14:59:59", 129801, 211, 2, "2024/03/31 12:00:00", 24, 0, 10142, 0, "今回の訓練もよく頑張ったな！\nしっかり休んで次に備えろよ！\nなんつーか、教え子が成長してくのを\n見るのは楽しいもんだな…", 1, "マコト", 211);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (0, "2030/12/17 14:59:59", 129801, 212, 2, "2024/03/31 12:00:00", 24, 0, 10142, 0, "おまえら、すげえじゃねえか！\nこれならもう、ひよっこ新兵なんて\n言えねえな。きっと騎士団でも\n大活躍間違いなしだぜ！", 2, "マコト", 212);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (6.65, "2030/12/17 14:59:59", 129801, 213, 1, "2024/03/31 12:00:00", 24, 0, 10142, 0, "敵との戦い方、状況判断の正確さ\n何より根性…どれも最高だったぞ！\nうかうかしてたら、教官のあたしまで\n追い抜かれちまうかもな…へへっ", 2, "マコト", 213);
INSERT INTO `v1_01f4db4e9f4f3a374f63120a5b22ccde35f5894ac151111ec7ef2473cddcf2be` VALUES (3.05, "2030/12/17 14:59:59", 129801, 214, 6, "2024/03/31 12:00:00", 24, 0, 10142, 0, "あたしの指導が良かった？\nいやいや、ここまで強くなれたのは、\n他でもないおまえたち自身が努力した\nおかげだよ。改めて…おめでとうっ！", 1, "マコト", 214);
